description:
Write `parseArgs(argv)` for a small tool. `argv` is the arguments after the program name (what `process.argv.slice(2)` gives). Return `{ flags, options, positional }`:

- `--name value` puts `name: "value"` in `options`;
- `--name=value` does the same;
- `--name` followed by nothing, or by another `--...`, is a flag: `flags` gets `name: true`;
- `--` on its own means everything after it is positional, even if it starts with `--`;
- anything else is added to `positional` in order.

```javascript
parseArgs(["--limit", "5", "in.csv", "--verbose", "--out=x.txt", "--", "--weird"]);
// { flags: { verbose: true }, options: { limit: "5", out: "x.txt" }, positional: ["in.csv", "--weird"] }
```

starter.solution.js:
function parseArgs(argv) {
  return { flags: {}, options: {}, positional: argv };
}

solution.solution.js:
function parseArgs(argv) {
  const flags = {};
  const options = {};
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--") {
      positional.push(...argv.slice(i + 1));
      break;
    }
    if (arg.startsWith("--")) {
      const body = arg.slice(2);
      const eq = body.indexOf("=");
      if (eq >= 0) {
        options[body.slice(0, eq)] = body.slice(eq + 1);
      } else if (i + 1 < argv.length && !argv[i + 1].startsWith("--")) {
        options[body] = argv[++i];
      } else {
        flags[body] = true;
      }
    } else {
      positional.push(arg);
    }
  }
  return { flags, options, positional };
}

unitTests:
test("the example", () => {
  checkEq(parseArgs(["--limit", "5", "in.csv", "--verbose", "--out=x.txt", "--", "--weird"]),
    { flags: { verbose: true }, options: { limit: "5", out: "x.txt" }, positional: ["in.csv", "--weird"] });
});

test("edges", () => {
  checkEq(parseArgs([]), { flags: {}, options: {}, positional: [] });
  checkEq(parseArgs(["--a", "--b"]), { flags: { a: true, b: true }, options: {}, positional: [] });
  checkEq(parseArgs(["--empty="]), { flags: {}, options: { empty: "" }, positional: [] });
  checkEq(parseArgs(["x", "--", "y"]), { flags: {}, options: {}, positional: ["x", "y"] });
});

